  "check_code": "def _result(ok, detail):
    return {"score": 1.0 if ok else 0.0, "detail": detail}


def _query(ws, system_name, sql, params=()):
    return db_query(ws, system_name, sql, params)


def check_reopened_work_package(ws):
    rows = _query(
        ws,
        "openproject_foia_actions",
        """
        SELECT current_status, percentage_done
        FROM corrective_work_packages
        WHERE work_package_id = ?
        """,
        ("CWP-FY24-052",),
    )
    ok = len(rows) == 1 and rows[0]["current_status"] == "IN_PROGRESS" and rows[0]["percentage_done"] == 98
    return _result(ok, f"target work package rows={rows}")


def _target_history(ws):
    return _query(
        ws,
        "openproject_foia_actions",
        """
        SELECT status_event_id, owner_id, status_code, status_date, reason_code,
               status_note, approved_by_owner_id, created_at
        FROM work_package_status_history
        WHERE work_package_id = ?
        ORDER BY status_date DESC, created_at DESC, status_event_id DESC
        """,
        ("CWP-FY24-052",),
    )


def check_authorized_transition_history(ws):
    rows = _target_history(ws)
    if len(rows) != 3:
        return _result(False, f"expected an appended transition; rows={rows}")
    newest, prior = rows[0], rows[1]
    ok = (
        newest["status_code"] == "IN_PROGRESS"
        and newest["reason_code"] == "VALIDATION_EXCEPTION"
        and newest["owner_id"] == "OWN-EPA-NFO-007"
        and newest["approved_by_owner_id"] == "OWN-OGC-FOIA-003"
        and prior["status_code"] == "VALIDATION_PENDING"
        and newest["status_date"] > prior["status_date"]
    )
    return _result(ok, f"newest={newest}; prior={prior}")


def check_traceable_exception_note(ws):
    rows = _target_history(ws)
    if not rows:
        return _result(False, "target history is missing")
    note = " ".join(str(rows[0]["status_note"] or "").lower().replace("-", " ").split())
    has_counts = "98" in note and "96" in note
    has_two = "two" in note or "2" in note
    has_action = any(word in note for word in ("rework", "remediation", "remediate", "reopen"))
    ok = has_counts and has_two and has_action
    return _result(ok, f"newest transition note={rows[0]['status_note']!r}")


def check_unrelated_actions_unchanged(ws):
    rows = _query(
        ws,
        "openproject_foia_actions",
        """
        SELECT work_package_id, current_status, percentage_done, updated_at
        FROM corrective_work_packages
        WHERE work_package_id IN (?, ?)
        ORDER BY work_package_id
        """,
        ("CWP-FY24-041", "CWP-FY24-044"),
    )
    expected = [
        {"work_package_id": "CWP-FY24-041", "current_status": "VALIDATION_PENDING", "percentage_done": 96, "updated_at": "2024-10-01T15:14:00Z"},
        {"work_package_id": "CWP-FY24-044", "current_status": "VALIDATION_PENDING", "percentage_done": 92, "updated_at": "2024-10-02T18:33:00Z"},
    ]
    return _result(rows == expected, f"unrelated action rows={rows}")


